import json
from pathlib import Path
p=Path('data/words.json');d=json.loads(p.read_text(encoding='utf-8'));wm={w['id']:w for w in d['words']}
M={
'stall':'马厩里用隔板分出一格，马在自己的位置低头吃草','stamp':'橡皮印章蘸上印泥，重重压在文件角落','standard':'阅兵场上所有旗杆高度一致，队伍按同一尺度排列','standpoint':'两个人站在地图两侧，从各自位置观察同一条路线','staple':'金属钉脚穿过几张纸，背面弯折后把纸固定住','star':'夜空中一点明亮光体在其他暗点之间清楚可见','stare':'人站在窗前长时间盯着远处，眼睛几乎不眨','start':'发令声响起，赛跑者同时从起点冲出','startle':'门后突然传出巨响，等候者肩膀猛地抬起','starve':'空碗放在桌上几天，孩子疲惫地望向厨房','steady':'桥梁经受风吹仍保持平稳，水面下的支柱没有晃动','steak':'厚肉片在烤架上变色，夹子把它翻到另一面','steal':'手从桌面悄悄拿走钱包，主人没有察觉','steam':'热水上方升起白雾，沿窗玻璃凝成小水珠','steamer':'船舶从港口驶出，烟囱向后吐出一缕白汽','steel':'银灰色梁柱支撑着厂房屋顶，表面坚硬平直','steep':'山坡突然向上抬起，登山者必须抓住绳索','steer':'驾驶者转动方向盘，车辆沿弯曲道路改变方向','stem':'花茎从土中直立向上，顶端托着一朵花','step':'脚从一级石阶抬起，落到紧接着的下一级','stereo':'两只音箱分列房间两侧，音乐从左右同时传来','stern':'船尾在浪后上下起伏，旗帜固定在最后一端','steward':'工作人员在车厢里检查座位和乘客需要的物品','stick':'细木棍插进湿泥，拔出时带起一小块土','sticky':'糖浆沾在手指上，触碰其他东西时会拉出细丝','stiff':'冻硬的布料无法弯曲，衣架撑着它保持直线','stimulate':'轻微电流接通后，实验装置的指针开始活跃摆动','sting':'蜜蜂尾端的刺碰到皮肤，留下一个小红点','stir':'勺子在锅里绕圈搅动，液体和配料混在一起','stitch':'针线穿过布面，连续小针脚把裂口合拢','stock':'仓库货架上按类别堆着待售箱子','stocking':'长袜从脚踝一直套到膝下，挂在晾衣架上','stomach':'食物沿管道进入腹部的囊状器官，那里正在消化','stone':'河床上的硬石被水流磨得圆滑，彼此挤在一起','stool':'柜台旁放着一张没有靠背的高凳','stoop':'人弯下上身从地面捡起掉落的钥匙','stop':'红灯亮起，车辆在白线前逐渐停住','storey':'建筑剖面显示楼板一层层叠在屋顶下','storm':'乌云压低天空，强风把树枝向同一方向吹弯','story':'书页按顺序讲述一个人从起点到结尾的经历','stove':'炉灶上的锅正加热，火焰从金属底部升起','straight':'绳子从起点拉到终点，中间没有任何弯折','straightforward':'地图上的路线只有一条直路，沿途没有岔口','strange':'熟悉街道中央出现一件从未见过的物品','stranger':'陌生人站在门口，屋里的人不认识这张脸','strap':'皮带穿过扣环，把箱子紧紧固定住','strategy':'棋盘旁摊着几步计划，棋手先标出下一轮路线','straw':'细管插进饮料杯，液体沿管道被吸入口中','strawberry':'红色果实躲在叶片下，表面布满细小籽粒','stream':'清水沿浅沟持续流动，绕过石块汇向低处','streamline':'机器外壳被削去多余凸起，空气沿光滑表面流过','street':'两排房屋之间铺着道路，行人沿路向前','strength':'粗绳承受重物的拉力，纤维仍然没有断裂','strengthen':'桥墩外加了一层钢板，结构承重能力变强','strenuous':'登山者连续攀爬陡坡，汗水浸透了衣服','stress':'重物压在薄梁中央，受力处出现明显弯曲','stretch':'橡皮带被两只手向相反方向拉长','stride':'行人迈出很大一步，脚印间距明显超过平常','strife':'两队隔着栅栏互相推搡，谁也不肯后退','strike':'锤子落下击中金属片，瞬间发出清脆声响','striking':'整齐队列中一件鲜红物品格外醒目，所有人都转头看','string':'细线穿过针眼并沿布面拉直，末端缠成一圈','strip':'手指把纸带上的外层覆膜一点点撕掉','stripe':'布面上几条颜色不同的长带平行排列','strive':'运动员咬紧牙关向终点跑，身体不断向前用力','stroke':'画笔沿墙面轻轻移动，留下一道连续色带','stroll':'人沿公园小路慢慢走，脚步没有赶路的节奏','strong':'粗木梁支住屋顶，几个人合力也推不动','struggle':'登山者抓着湿岩面向上攀，身体不断滑回','stubborn':'骡子站在路中央不肯移动，缰绳被拉得笔直','student':'学生坐在桌前翻开教材，旁边放着练习本','studio':'房间里摆着画架、灯和录音设备，供创作使用','study':'台灯照着书页，读者用笔在边上做记录','stuff':'抽屉里塞满各种小物件，找一件东西要翻动许久','stumble':'脚尖碰到石块，行走者踉跄几步才站稳','stun':'强光突然照来，场上的人一时失去反应','stupid':'人把钥匙放进冰箱后四处寻找，旁边的人无奈摇头','sturdy':'厚木桌经受推撞仍然稳固，桌腿没有变形','style':'画廊中几幅作品线条和用色显示出同一位作者的风格','submarine':'黑色船体潜入水下，只有一根细长桅杆露在海面','substantial':'天平一侧放着沉重金属块，另一侧的小物体无法压过它','subtle':'白纸上只有一条极细的色差，靠近后才看得出来','suburb':'城市边缘一排低层住宅沿道路展开，远处仍看得见高楼','subway':'人们沿地下站台登车，列车从隧道深处驶来','suck':'吸管从杯中抽取液体，水面沿管子向上升','sudden':'平静水面毫无预兆地落下一颗石子，波纹立刻散开','suffice':'桌上只有一盏灯，却足以照亮整页文件','sugar':'白色晶粒从罐中倒出，落在茶水表面逐渐溶解','suicide':'高处边缘立着警示栏，工作人员及时把独处者带回安全处','sulfur':'黄色晶体放在实验台上，旁边贴着元素标签'}
assert len(M)==90 and set(M)<=set(wm)
for k,v in M.items():wm[k]['core_image']=v
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('[OK]',len(M))
